//! Bundled atlas seed data loader.
//!
//! `atlas.json` (generated by `scripts/gen-seed.py`) carries the starting
//! catalog: expansions, continents, zones, resources, and representative node
//! priors (`source='seed'`). Loading is idempotent and upgrade-safe:
//!
//! - Catalog tables upsert by id (seed stays canonical; zones/resources are
//!   not user-editable).
//! - Seed observations are snapshot-replaced (DELETE + INSERT in one txn).
//! - Bridge-created placeholders (`map-<id>`, `item:<id>`) that collide with
//!   seed rows by map/item id are merged away: referencing rows are remapped
//!   and stat tables folded, so sync-before-seed ordering can never fork the
//!   catalog.

use crate::error::Result;
use crate::models::source;
use rusqlite::{Connection, OptionalExtension};
use serde::Deserialize;

const SEED_JSON: &str = include_str!("seed/atlas.json");

#[derive(Debug, Deserialize)]
struct SeedFile {
    expansions: Vec<SeedExpansion>,
    continents: Vec<SeedContinent>,
    zones: Vec<SeedZone>,
    categories: Vec<SeedCategory>,
    resources: Vec<SeedResource>,
    observations: Vec<SeedObs>,
}

#[derive(Debug, Deserialize)]
struct SeedExpansion {
    id: String,
    name: String,
    short: String,
    sort_order: i64,
}

#[derive(Debug, Deserialize)]
struct SeedContinent {
    id: String,
    expansion_id: String,
    name: String,
}

#[derive(Debug, Deserialize)]
struct SeedZone {
    id: String,
    continent_id: String,
    name: String,
    map_id: Option<i64>,
    yards_per_unit: f64,
}

#[derive(Debug, Deserialize)]
struct SeedCategory {
    id: String,
    key: String,
    name: String,
}

#[derive(Debug, Deserialize)]
struct SeedResource {
    id: String,
    category_id: String,
    key: String,
    name: String,
    item_id: Option<i64>,
    quality: i64,
}

#[derive(Debug, Deserialize)]
struct SeedObs {
    zone_id: String,
    resource_id: String,
    map_id: Option<i64>,
    x: f64,
    y: f64,
    yield_qty: Option<f64>,
}

#[derive(Debug, Default, Clone, Copy)]
pub struct SeedStats {
    pub expansions: usize,
    pub continents: usize,
    pub zones: usize,
    pub resources: usize,
    pub observations: usize,
    pub merged_zones: usize,
    pub merged_resources: usize,
}

pub fn load(conn: &mut Connection) -> Result<SeedStats> {
    let seed: SeedFile = serde_json::from_str(SEED_JSON).map_err(|e| {
        crate::error::AppError::provider(format!("bundled seed data corrupt: {e}"))
    })?;
    let tx = conn.transaction()?;
    let mut stats = SeedStats::default();

    for e in &seed.expansions {
        tx.execute(
            "INSERT INTO expansions (id, name, short, sort_order) VALUES (?1, ?2, ?3, ?4)
             ON CONFLICT(id) DO UPDATE SET name = excluded.name, short = excluded.short,
                                            sort_order = excluded.sort_order",
            rusqlite::params![e.id, e.name, e.short, e.sort_order],
        )?;
        stats.expansions += 1;
    }
    for c in &seed.continents {
        tx.execute(
            "INSERT INTO continents (id, expansion_id, name) VALUES (?1, ?2, ?3)
             ON CONFLICT(id) DO UPDATE SET expansion_id = excluded.expansion_id,
                                            name = excluded.name",
            rusqlite::params![c.id, c.expansion_id, c.name],
        )?;
        stats.continents += 1;
    }
    // Categories: seed is a subset-safe upsert (never deletes user-side `other` etc.).
    for c in &seed.categories {
        tx.execute(
            "INSERT INTO farm_categories (id, key, name) VALUES (?1, ?2, ?3)
             ON CONFLICT(id) DO UPDATE SET name = excluded.name",
            rusqlite::params![c.id, c.key, c.name],
        )?;
    }

    for z in &seed.zones {
        if let Some(map) = z.map_id {
            stats.merged_zones += merge_zone_placeholders(&tx, &z.id, map)?;
        }
        tx.execute(
            "INSERT INTO zones (id, continent_id, name, map_id, yards_per_unit)
             VALUES (?1, ?2, ?3, ?4, ?5)
             ON CONFLICT(id) DO UPDATE SET continent_id = excluded.continent_id,
                 name = excluded.name, map_id = excluded.map_id,
                 yards_per_unit = excluded.yards_per_unit",
            rusqlite::params![z.id, z.continent_id, z.name, z.map_id, z.yards_per_unit],
        )?;
        stats.zones += 1;
    }

    for r in &seed.resources {
        if let Some(item) = r.item_id {
            stats.merged_resources += merge_resource_placeholders(&tx, &r.id, item)?;
        }
        tx.execute(
            "INSERT INTO resources (id, category_id, key, name, item_id, quality)
             VALUES (?1, ?2, ?3, ?4, ?5, ?6)
             ON CONFLICT(id) DO UPDATE SET category_id = excluded.category_id,
                 key = excluded.key, name = excluded.name, item_id = excluded.item_id,
                 quality = excluded.quality",
            rusqlite::params![r.id, r.category_id, r.key, r.name, r.item_id, r.quality],
        )?;
        stats.resources += 1;
    }

    tx.execute(
        "DELETE FROM resource_observations WHERE source = ?1",
        rusqlite::params![source::SEED],
    )?;
    for o in &seed.observations {
        tx.execute(
            "INSERT INTO resource_observations
             (zone_id, resource_id, map_id, x, y, source, yield_qty, observed_at)
             VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, 0)",
            rusqlite::params![
                o.zone_id,
                o.resource_id,
                o.map_id,
                o.x,
                o.y,
                source::SEED,
                o.yield_qty
            ],
        )?;
        stats.observations += 1;
    }
    tx.commit()?;
    Ok(stats)
}

/// Remap every row pointing at placeholder zones sharing `map_id` onto `seed_id`.
/// Returns the number of placeholder zones absorbed.
fn merge_zone_placeholders(conn: &Connection, seed_id: &str, map_id: i64) -> Result<usize> {
    let olds: Vec<String> = conn
        .prepare("SELECT id FROM zones WHERE map_id = ?1 AND id != ?2")?
        .query_map(rusqlite::params![map_id, seed_id], |r| r.get(0))?
        .collect::<std::result::Result<_, _>>()?;
    for old in &olds {
        for (table, col) in [
            ("resource_observations", "zone_id"),
            ("farm_sessions", "zone_id"),
            ("saved_routes", "zone_id"),
        ] {
            conn.execute(
                &format!("UPDATE {table} SET {col} = ?1 WHERE {col} = ?2"),
                rusqlite::params![seed_id, old],
            )?;
        }
        merge_zone_stats(conn, old, seed_id)?;
        merge_crowd_zone(conn, old, seed_id)?;
        conn.execute("DELETE FROM zones WHERE id = ?1", rusqlite::params![old])?;
    }
    Ok(olds.len())
}

fn merge_zone_stats(conn: &Connection, old: &str, seed_id: &str) -> Result<()> {
    let old_row: Option<(i64, i64, f64, f64, f64, i64)> = conn
        .query_row(
            "SELECT sessions, total_seconds, avg_gph, efficiency, hit_rate, updated_at
             FROM personal_zone_stats WHERE zone_id = ?1",
            rusqlite::params![old],
            |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?, r.get(3)?, r.get(4)?, r.get(5)?)),
        )
        .optional()?;
    let Some((o_ses, o_sec, o_gph, o_eff, o_hit, o_upd)) = old_row else {
        return Ok(());
    };
    let seed_row: Option<(i64, i64, f64, f64, f64, i64)> = conn
        .query_row(
            "SELECT sessions, total_seconds, avg_gph, efficiency, hit_rate, updated_at
             FROM personal_zone_stats WHERE zone_id = ?1",
            rusqlite::params![seed_id],
            |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?, r.get(3)?, r.get(4)?, r.get(5)?)),
        )
        .optional()?;
    match seed_row {
        None => {
            conn.execute(
                "UPDATE personal_zone_stats SET zone_id = ?1 WHERE zone_id = ?2",
                rusqlite::params![seed_id, old],
            )?;
        }
        Some((s_ses, s_sec, s_gph, s_eff, s_hit, s_upd)) => {
            let total = (o_ses + s_ses).max(1) as f64;
            let wavg = |o: f64, s: f64| (o * o_ses as f64 + s * s_ses as f64) / total;
            conn.execute(
                "UPDATE personal_zone_stats SET sessions = ?1, total_seconds = ?2,
                 avg_gph = ?3, efficiency = ?4, hit_rate = ?5, updated_at = ?6
                 WHERE zone_id = ?7",
                rusqlite::params![
                    o_ses + s_ses,
                    o_sec + s_sec,
                    wavg(o_gph, s_gph),
                    wavg(o_eff, s_eff),
                    wavg(o_hit, s_hit),
                    o_upd.max(s_upd),
                    seed_id
                ],
            )?;
            conn.execute(
                "DELETE FROM personal_zone_stats WHERE zone_id = ?1",
                rusqlite::params![old],
            )?;
        }
    }
    Ok(())
}

fn merge_crowd_zone(conn: &Connection, old: &str, seed_id: &str) -> Result<()> {
    // Rows unique on (zone, resource, bx, by, day): fold on conflict.
    let rows: Vec<(String, i64, i64, i64, i64, i64, i64)> = conn
        .prepare(
            "SELECT resource_id, bucket_x, bucket_y, day_bucket, success, trials, contributors
             FROM crowd_observations WHERE zone_id = ?1",
        )?
        .query_map(rusqlite::params![old], |r| {
            Ok((r.get(0)?, r.get(1)?, r.get(2)?, r.get(3)?, r.get(4)?, r.get(5)?, r.get(6)?))
        })?
        .collect::<std::result::Result<_, _>>()?;
    for (res, bx, by, day, succ, trials, contrib) in rows {
        let existing: Option<(i64, i64, i64)> = conn
            .query_row(
                "SELECT success, trials, contributors FROM crowd_observations
                 WHERE zone_id = ?1 AND resource_id = ?2 AND bucket_x = ?3
                   AND bucket_y = ?4 AND day_bucket = ?5",
                rusqlite::params![seed_id, res, bx, by, day],
                |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)),
            )
            .optional()?;
        match existing {
            None => {
                conn.execute(
                    "UPDATE crowd_observations SET zone_id = ?1
                     WHERE zone_id = ?2 AND resource_id = ?3 AND bucket_x = ?4
                       AND bucket_y = ?5 AND day_bucket = ?6",
                    rusqlite::params![seed_id, old, res, bx, by, day],
                )?;
            }
            Some((e_succ, e_trials, e_contrib)) => {
                conn.execute(
                    "UPDATE crowd_observations SET success = ?1, trials = ?2,
                     contributors = ?3 WHERE zone_id = ?4 AND resource_id = ?5
                     AND bucket_x = ?6 AND bucket_y = ?7 AND day_bucket = ?8",
                    rusqlite::params![
                        e_succ + succ,
                        e_trials + trials,
                        e_contrib.max(contrib),
                        seed_id,
                        res,
                        bx,
                        by,
                        day
                    ],
                )?;
                conn.execute(
                    "DELETE FROM crowd_observations
                     WHERE zone_id = ?1 AND resource_id = ?2 AND bucket_x = ?3
                       AND bucket_y = ?4 AND day_bucket = ?5",
                    rusqlite::params![old, res, bx, by, day],
                )?;
            }
        }
    }
    Ok(())
}

/// Remap every row pointing at placeholder resources sharing `item_id` onto `seed_id`.
fn merge_resource_placeholders(conn: &Connection, seed_id: &str, item_id: i64) -> Result<usize> {
    let olds: Vec<String> = conn
        .prepare("SELECT id FROM resources WHERE item_id = ?1 AND id != ?2")?
        .query_map(rusqlite::params![item_id, seed_id], |r| r.get(0))?
        .collect::<std::result::Result<_, _>>()?;
    for old in &olds {
        for (table, col) in [
            ("resource_observations", "resource_id"),
            ("farm_session_items", "resource_id"),
        ] {
            conn.execute(
                &format!("UPDATE {table} SET {col} = ?1 WHERE {col} = ?2"),
                rusqlite::params![seed_id, old],
            )?;
        }
        // farm_session_items PK is (session_id, item_id) — resource_id is payload. Safe.
        merge_resource_stats(conn, old, seed_id)?;
        merge_crowd_resource(conn, old, seed_id)?;
        conn.execute("DELETE FROM resources WHERE id = ?1", rusqlite::params![old])?;
    }
    Ok(olds.len())
}

fn merge_resource_stats(conn: &Connection, old: &str, seed_id: &str) -> Result<()> {
    let old_row: Option<(i64, f64, f64, f64)> = conn
        .query_row(
            "SELECT gathers, total_qty, avg_yield, avg_gold_per_gather
             FROM personal_resource_stats WHERE resource_id = ?1",
            rusqlite::params![old],
            |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?, r.get(3)?)),
        )
        .optional()?;
    let Some((o_g, o_q, o_y, o_gold)) = old_row else {
        return Ok(());
    };
    let seed_row: Option<(i64, f64, f64, f64)> = conn
        .query_row(
            "SELECT gathers, total_qty, avg_yield, avg_gold_per_gather
             FROM personal_resource_stats WHERE resource_id = ?1",
            rusqlite::params![seed_id],
            |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?, r.get(3)?)),
        )
        .optional()?;
    match seed_row {
        None => {
            conn.execute(
                "UPDATE personal_resource_stats SET resource_id = ?1 WHERE resource_id = ?2",
                rusqlite::params![seed_id, old],
            )?;
        }
        Some((s_g, s_q, s_y, s_gold)) => {
            let total = (o_g + s_g).max(1) as f64;
            let wavg = |o: f64, s: f64| (o * o_g as f64 + s * s_g as f64) / total;
            conn.execute(
                "UPDATE personal_resource_stats SET gathers = ?1, total_qty = ?2,
                 avg_yield = ?3, avg_gold_per_gather = ?4 WHERE resource_id = ?5",
                rusqlite::params![o_g + s_g, o_q + s_q, wavg(o_y, s_y), wavg(o_gold, s_gold), seed_id],
            )?;
            conn.execute(
                "DELETE FROM personal_resource_stats WHERE resource_id = ?1",
                rusqlite::params![old],
            )?;
        }
    }
    Ok(())
}

fn merge_crowd_resource(conn: &Connection, old: &str, seed_id: &str) -> Result<()> {
    let rows: Vec<(String, i64, i64, i64, i64, i64, i64)> = conn
        .prepare(
            "SELECT zone_id, bucket_x, bucket_y, day_bucket, success, trials, contributors
             FROM crowd_observations WHERE resource_id = ?1",
        )?
        .query_map(rusqlite::params![old], |r| {
            Ok((r.get(0)?, r.get(1)?, r.get(2)?, r.get(3)?, r.get(4)?, r.get(5)?, r.get(6)?))
        })?
        .collect::<std::result::Result<_, _>>()?;
    for (zone, bx, by, day, succ, trials, contrib) in rows {
        let existing: Option<(i64, i64, i64)> = conn
            .query_row(
                "SELECT success, trials, contributors FROM crowd_observations
                 WHERE zone_id = ?1 AND resource_id = ?2 AND bucket_x = ?3
                   AND bucket_y = ?4 AND day_bucket = ?5",
                rusqlite::params![zone, seed_id, bx, by, day],
                |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)),
            )
            .optional()?;
        match existing {
            None => {
                conn.execute(
                    "UPDATE crowd_observations SET resource_id = ?1
                     WHERE zone_id = ?2 AND resource_id = ?3 AND bucket_x = ?4
                       AND bucket_y = ?5 AND day_bucket = ?6",
                    rusqlite::params![seed_id, zone, old, bx, by, day],
                )?;
            }
            Some((e_succ, e_trials, e_contrib)) => {
                conn.execute(
                    "UPDATE crowd_observations SET success = ?1, trials = ?2,
                     contributors = ?3 WHERE zone_id = ?4 AND resource_id = ?5
                     AND bucket_x = ?6 AND bucket_y = ?7 AND day_bucket = ?8",
                    rusqlite::params![
                        e_succ + succ,
                        e_trials + trials,
                        e_contrib.max(contrib),
                        zone,
                        seed_id,
                        bx,
                        by,
                        day
                    ],
                )?;
                conn.execute(
                    "DELETE FROM crowd_observations
                     WHERE zone_id = ?1 AND resource_id = ?2 AND bucket_x = ?3
                       AND bucket_y = ?4 AND day_bucket = ?5",
                    rusqlite::params![zone, old, bx, by, day],
                )?;
            }
        }
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{atlas, migrations, storage};

    fn db() -> Connection {
        let mut conn = storage::open_memory().unwrap();
        migrations::migrate(&mut conn).unwrap();
        conn
    }

    #[test]
    fn seed_loads_expected_catalog() {
        let mut conn = db();
        let stats = load(&mut conn).unwrap();
        assert_eq!(stats.expansions, 2);
        assert_eq!(stats.zones, 6);
        assert_eq!(stats.resources, 8);
        assert!(stats.observations > 500);
        assert_eq!(stats.merged_zones, 0);
        // Idempotent catalog, snapshot observations.
        let again = load(&mut conn).unwrap();
        assert_eq!(again.observations, stats.observations);
        let n: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM resource_observations WHERE source = 'seed'",
                rusqlite::params![],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(n as usize, stats.observations);
    }

    #[test]
    fn seed_merges_bridge_placeholders() {
        let mut conn = db();
        // Simulate a sync that happened before the seed existed.
        let zone = atlas::ensure_zone_for_map(&conn, Some(2248), Some("Isle of Dorn")).unwrap();
        assert_eq!(zone, "map-2248");
        let res =
            atlas::ensure_resource_for_item(&conn, Some(161502), Some("Bismuth"), Some("mining"))
                .unwrap();
        assert_eq!(res, "item:161502");
        conn.execute(
            "INSERT INTO resource_observations (zone_id, resource_id, x, y, source)
             VALUES (?1, ?2, 10.0, 10.0, 'addon')",
            rusqlite::params![zone, res],
        )
        .unwrap();

        let stats = load(&mut conn).unwrap();
        assert_eq!(stats.merged_zones, 1);
        assert_eq!(stats.merged_resources, 1);
        // Placeholders gone, observation remapped onto canonical rows.
        let ids: Vec<String> = conn
            .prepare("SELECT id FROM zones ORDER BY id")
            .unwrap()
            .query_map(rusqlite::params![], |r| r.get(0))
            .unwrap()
            .collect::<std::result::Result<_, _>>()
            .unwrap();
        assert!(ids.contains(&"isle-of-dorn".to_string()));
        assert!(!ids.iter().any(|id| id == "map-2248"));
        let (z, r): (String, String) = conn
            .query_row(
                "SELECT zone_id, resource_id FROM resource_observations WHERE source = 'addon'",
                rusqlite::params![],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .unwrap();
        assert_eq!(z, "isle-of-dorn");
        assert_eq!(r, "bismuth");
    }
}
